import { useEffect, useState } from "react";
import LeaveService from "../Services/LeaveService";

const ViewLeaves = () => {

    const [leaves, setLeaves] = useState([]);

    useEffect(() => {
        LeaveService.getLeaves()
            .then(res => setLeaves(res.data))
            .catch(err => console.log(err));
    }, []);

    const updateStatus = (id, status) => {
        LeaveService.updateLeaveStatus(id, status).then(() => {
            setLeaves(leaves.map(l =>
                l.lid === id ? { ...l, status } : l
            ));
        });
    };

    return (
        <div style={{ padding: '36px' }}>

            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '28px' }}>
                <h3 style={{ fontWeight: '700' }}>
                    <i className="fa fa-calendar me-2"></i>Leave Requests
                </h3>
                <span>Total: {leaves.length}</span>
            </div>

            <div style={{ background: '#fff', borderRadius: '8px', boxShadow: '0 2px 12px rgba(0,0,0,0.08)', overflow: 'hidden' }}>
                <table className="table table-hover mb-0">

                    <thead style={{ background: '#414447', color: '#fff' }}>
                        <tr>
                            <th>Sl No</th>
                            <th>Employee ID</th>
                            <th>Leave Type</th>
                            <th>Start Date</th>
                            <th>End Date</th>
                            <th>Status</th>
                            <th>Action</th>
                        </tr>
                    </thead>

                    <tbody>
                        {leaves.map((leave, index) => (
                            <tr key={leave.lid}>
                                <td>{index + 1}</td>
                                <td>{leave.employee?.id}</td>
                                <td>{leave.leaveType}</td>
                                <td>{leave.startDate}</td>
                                <td>{leave.endDate}</td>
                                <td>
                                    <span style={{
                                        padding: "6px 12px",
                                        borderRadius: "20px",
                                        fontSize: "12px",
                                        fontWeight: "600",
                                        color: "#fff",
                                        background:
                                            leave.status === "APPROVED" ? "#28a745" :
                                            leave.status === "REJECTED" ? "#dc3545" :
                                            "#ffc107"
                                    }}>
                                        {leave.status}
                                    </span>
                                </td>
                                <td>
                                    {leave.status === "PENDING" ? (
                                        <>
                                            <button
                                                onClick={() => updateStatus(leave.lid, "APPROVED")}
                                                style={{ marginRight: "10px" }}
                                            >
                                                Approve
                                            </button>

                                            <button
                                                onClick={() => updateStatus(leave.lid, "REJECTED")}
                                            >
                                                Reject
                                            </button>
                                        </>
                                    ) : (
                                        <span style={{ color: "#6c757d", fontSize: "13px" }}>
                                            Action Completed
                                        </span>
                                    )}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default ViewLeaves;
